package mz.co.aprendaacodar.payment.entity;
import jakarta.persistence.*;import mz.co.aprendaacodar.common.entity.BaseEntity;import mz.co.aprendaacodar.common.enums.Enums.*;import mz.co.aprendaacodar.common.exception.BusinessException;import mz.co.aprendaacodar.enrollment.entity.CourseEnrollment;import mz.co.aprendaacodar.user.entity.User;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="payments") public class Payment extends BaseEntity {
 @ManyToOne(optional=false,fetch=FetchType.LAZY) private CourseEnrollment enrollment;@Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private PaymentMethod method;@Column(nullable=false,precision=12,scale=2) private BigDecimal amount;@Column(nullable=false,length=3) private String currency;@Column(nullable=false,unique=true,length=150) private String transactionReference;@Column(length=500) private String proofFileKey;@Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private PaymentStatus status;@Column(nullable=false) private Instant submittedAt;private Instant reviewedAt;@ManyToOne(fetch=FetchType.LAZY) private User reviewedBy;@Column(columnDefinition="TEXT") private String rejectionReason;
 protected Payment(){}public Payment(CourseEnrollment e,PaymentMethod m,String ref,String key){enrollment=e;method=m;transactionReference=ref;proofFileKey=key;amount=e.getAgreedPrice();currency=e.getCurrency();status=PaymentStatus.PENDING_REVIEW;submittedAt=Instant.now();}
 public void approve(User admin){if(status!=PaymentStatus.PENDING_REVIEW)throw new BusinessException("O pagamento já foi processado.");status=PaymentStatus.APPROVED;reviewedAt=Instant.now();reviewedBy=admin;}
 public void reject(User admin,String reason){if(status!=PaymentStatus.PENDING_REVIEW)throw new BusinessException("O pagamento já foi processado.");status=PaymentStatus.REJECTED;reviewedAt=Instant.now();reviewedBy=admin;rejectionReason=reason;}
 public CourseEnrollment getEnrollment(){return enrollment;}public PaymentStatus getStatus(){return status;}public BigDecimal getAmount(){return amount;}public String getCurrency(){return currency;}public PaymentMethod getMethod(){return method;}public String getTransactionReference(){return transactionReference;}public String getProofFileKey(){return proofFileKey;}public Instant getSubmittedAt(){return submittedAt;}public Instant getReviewedAt(){return reviewedAt;}public String getRejectionReason(){return rejectionReason;}
}
